의사코드:
  SceneModule 현재 시퀀스 지정, EntityModule 갱신 범위 지정(FUN_71008a30c0)
  for f in s.pending(+0x18, 등록 순): f.StartUpdate(); InitializeFiber(f); s.active(+0x30).push_back(f); s.dirty(+0x78) = 1;
  s.pending.clear();
  if (s.dirty) { s.dirty = 0; stable_merge_sort(s.active, by f.priority(+0x7C) ascending); }   // FUN_710018f740
  for f in s.active(앞에서부터):
    if (IsPaused(f.pauseLevel(+0x74))) continue;
    s.current(+0x80) = f; Resume(f);       // FUN_710018dbb0
    if (f.stopped || f.completed) { s.active.erase(f); if (!f.autoDestroy(+0xE0)) s.finished(+0x48).push_back(f); else delete f.owner; }
    s.current = null;
  s.flushDestroyRequests();                // FUN_710018ee70
